        rf"{re.escape(start_marker)}.*?{re.escape(end_marker)}\n?", re.DOTALL
    );
    if pattern.search(content) {
        content = pattern.sub(new_block, content);
        action = "Updated";
    } else {
        content = content.rstrip() + "\n\n" + new_block
            if content.strip()
            else new_block;
        action = "Added";
    }
    try {
        os.makedirs(os.path.dirname(config_file), exist_ok=True);
        with open(config_file, "w", encoding="utf-8") as f {
            f.write(content);
        }
        console.print(f"Completion script written to {comp_file}");
        console.print(f"{action} source line in {config_file}");
        console.print(f"Run 'source {config_file}' or restart your shell to activate.");
        return 0;
    } except Exception as e {
        console.error(f"Error writing config: {e}");
        return 1;
    }
}

impl gen_jir_registry(verify: bool = False) -> int {
    import from jaclang.jac0core.gen_jir_registry { generate }
    import from pathlib { Path }
    import tempfile;
    import subprocess;
    import sys;
    import jaclang;

    registry_path = Path(jaclang.__file__).parent / "jac0core" / "jir_registry.jac";

    try {
        content = generate();
    } except Exception as e {
        console.error(f"Failed to generate registry: {e}");
        return 1;
    }

    import os;
    try {
        with tempfile.TemporaryDirectory() as fmt_dir {
            tmp_path = os.path.join(fmt_dir, "jir_registry.jac");
            with open(tmp_path, 'w', encoding='utf-8') as tmp {
                tmp.write(content);
            }
            with open(
                os.path.join(fmt_dir, "jac.toml"), 'w', encoding='utf-8'
            ) as cfg {
                cfg.write("[check.lint]\nselect = [\"all\"]\n");
            }
            subprocess.run(
                [sys.executable, '-m', 'jaclang', 'fmt', '--lintfix', tmp_path],
                capture_output=True,
                cwd=fmt_dir
            );
            content = Path(tmp_path).read_text(encoding="utf-8");
        }
    } except Exception {
        ;
    }

    if verify {
        current = registry_path.read_text(encoding="utf-8")
            if registry_path.exists()
            else "";
        if current == content {
            console.print("jir_registry.jac is up to date.");
            return 0;
        } else {
            console.error(
                "jir_registry.jac is OUT OF DATE. "
                "Run `jac gen-jir-registry` to update."
            );
            return 1;
        }
    }

    registry_path.write_text(content);
    console.print(f"Generated {registry_path} ({len(content)} bytes)");
    return 0;
}

impl gen_uni_dispatch(verify: bool = False) -> int {
    import from jaclang.jac0core.gen_uni_dispatch { write_all, verify_all }
    if verify {
        stale = verify_all();
        for rel in stale {
            console.error(f"Dispatch annex OUT OF DATE: {rel}");
        }
        if stale {
            console.error("Run `jac gen-uni-dispatch` to update.");
            return 1;
        }
        console.print("All dispatch annexes are up to date.");
        return 0;
    }
    for msg in write_all() {
        console.print(msg);
    }
    return 0;
}

impl gen_cli_manifest(verify: bool = False) -> int {
    import from jaclang.cli.gen_cli_manifest { write_routes, verify_drift }
    if verify {
        drift = verify_drift();
        for msg in drift {
            console.error(f"{msg}");
        }
        if drift {
            console.error("Run `jac gen-cli-manifest` to update.");
            return 1;
        }
        console.print("Manifest route table is up to date.");
        return 0;
    }
    out = write_routes();
    console.print(f"Generated {out}");
    return 0;
}

